        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer in = new StreamTokenizer(br);
        in.resetSyntax();
        in.wordChars(33, 255);
        in.whitespaceChars(0, 32);
        in.nextToken(); int n = Integer.parseInt(in.sval);
        in.nextToken(); long d = Long.parseLong(in.sval);
        long[] credits = new long[n];
        for (int i = 0; i < n; i++) { in.nextToken(); credits[i] = Long.parseLong(in.sval); }
        int[][] edges = new int[Math.max(0, n - 1)][2];
        for (int i = 0; i < n - 1; i++) {
            in.nextToken(); edges[i][0] = Integer.parseInt(in.sval);
            in.nextToken(); edges[i][1] = Integer.parseInt(in.sval);
        }
        System.out.println(maxPreservedCredits(n, d, credits, edges));
